// MessageHandler receives a ProtocolMessage
type MessageHandler func(msg types.ProtocolMessage)

// Network defines the behaviour used by the distributed components. It enables tests to use a mock implementation.
//
// Deprecated: Use p2pconsensus.P2PConsensusManager for new development.
type Network interface {
	Initialize() error
	CreateNetwork(cfg types.NetworkConfig) (string, error)
	JoinNetwork(networkID string, bootstrapPeers []string) error
	LeaveNetwork(networkID string) error

	AddCollectionToNetwork(networkID, collectionName string) error
	RemoveCollectionFromNetwork(networkID, collectionName string) error
	GetNetworkCollections(networkID string) []string

	BroadcastMessage(networkID string, msg types.ProtocolMessage) error
	SendToPeer(peerID string, networkID string, msg types.ProtocolMessage) error
	OnMessage(mt types.MessageType, handler MessageHandler)

	GetNetworkStats(networkID string) *types.NetworkStats
	GetNetworks() []*types.NetworkConfig
	GetPeerID() string
	Shutdown() error
}

// DHTNode represents a node in our simplified DHT
type DHTNode struct {
	ID       string
	Address  string
	LastSeen time.Time
}

// DHTValue represents a value stored in the DHT
type DHTValue struct {
	Key       string      `json:"key"`
	Value     interface{} `json:"value"`
	TTL       int64       `json:"ttl"`
	Timestamp int64       `json:"timestamp"`
}

// NetworkManager is a custom P2P implementation with DHT-like functionality.
//
// Deprecated: Use p2pconsensus.P2PConsensusManager for new development.
type NetworkManager struct {
	ctx      context.Context
	cancel   context.CancelFunc
	listener *net.TCPListener
	peerID   string

	mu          sync.RWMutex
	networks    map[string]*types.NetworkConfig
	peers       map[string]*types.PeerInfo
	dht         map[string][]DHTNode  // Simple DHT: key -> list of nodes holding the value
	kvStore     map[string][]DHTValue // Simple DHT: key -> values
	connections map[string]net.Conn   // peerID -> connection
	stats       map[string]*types.NetworkStats
	handlers    map[types.MessageType][]MessageHandler
	initialized bool
}

// NewNetworkManager creates a new custom P2P network manager
func NewNetworkManager(ctx context.Context) *NetworkManager {
	// Generate a unique peer ID
	h := sha256.Sum256([]byte(fmt.Sprintf("%d-%d", time.Now().UnixNano(), rand.Int63())))
	peerID := hex.EncodeToString(h[:16])

	c, cancel := context.WithCancel(ctx)
	return &NetworkManager{
		ctx:         c,
		cancel:      cancel,
		peerID:      peerID,
		networks:    make(map[string]*types.NetworkConfig),
		peers:       make(map[string]*types.PeerInfo),
		dht:         make(map[string][]DHTNode),
		kvStore:     make(map[string][]DHTValue),
		connections: make(map[string]net.Conn),
		stats:       make(map[string]*types.NetworkStats),
		handlers:    make(map[types.MessageType][]MessageHandler),
	}
}

// DHT methods for global indexing

func (n *NetworkManager) PutDHT(key string, value interface{}, ttl time.Duration) error {
	n.mu.Lock()
	entry := DHTValue{
		Key:       key,
		Value:     value,
		TTL:       int64(ttl.Seconds()),
		Timestamp: time.Now().Unix(),
	}
	n.kvStore[key] = append(n.kvStore[key], entry)
	n.mu.Unlock()

	// In a real DHT, we would find the closest nodes to the key and store it there.
	// For this implementation, we broadcast a DHT announcement.
	return n.BroadcastMessage("", types.ProtocolMessage{
		Type:      types.MsgDHTPut,
		SenderID:  n.peerID,
		Timestamp: time.Now().UnixMilli(),
		Payload: map[string]interface{}{
			"key":   key,
			"value": value,
			"ttl":   ttl.Seconds(),
		},
	})
}

func (n *NetworkManager) GetDHT(key string) ([]interface{}, error) {
	n.mu.RLock()
	entries, ok := n.kvStore[key]
	n.mu.RUnlock()

	var results []interface{}
	now := time.Now().Unix()

	if ok {
		for _, entry := range entries {
			if entry.TTL == 0 || entry.Timestamp+entry.TTL > now {
				results = append(results, entry.Value)
			}
		}
	}

	// In a real DHT, if not found locally, we would query other nodes.
	// For now we just return what we have.
	return results, nil
}

func (n *NetworkManager) Initialize() error {
	n.mu.Lock()
	if n.initialized {
		n.mu.Unlock()
		return nil
	}

	// Start TCP listener with a timeout to prevent hanging in tests
	tcpAddr, err := net.ResolveTCPAddr("tcp", "127.0.0.1:0")
	if err != nil {
		n.mu.Unlock()
		return fmt.Errorf("failed to resolve TCP address: %v", err)
	}
	listener, err := net.ListenTCP("tcp", tcpAddr)
	if err != nil {
		n.mu.Unlock()
		return fmt.Errorf("failed to start listener: %v", err)
	}

	// Set a deadline to prevent the accept loop from blocking forever
	listener.SetDeadline(time.Now().Add(1 * time.Second))

	n.listener = listener
	n.initialized = true

	// Register DHT handlers - unlock first to avoid deadlock
	n.mu.Unlock()

	n.OnMessage(types.MsgDHTPut, func(msg types.ProtocolMessage) {
		payload, ok := msg.Payload.(map[string]interface{})
		if !ok {
			return
		}

		key, _ := payload["key"].(string)
		value := payload["value"]
		ttlFloat, _ := payload["ttl"].(float64)

		n.mu.Lock()
		n.kvStore[key] = append(n.kvStore[key], DHTValue{
			Key:       key,
			Value:     value,
			TTL:       int64(ttlFloat),
			Timestamp: time.Now().Unix(),
		})
		n.mu.Unlock()
	})

	// Start accepting connections with a non-blocking initial check
	go n.acceptConnections()

	log.Printf("Custom P2P node initialized: %s on %s", n.peerID, listener.Addr().String())
	return nil
}

func (n *NetworkManager) acceptConnections() {
	for {
		select {
		case <-n.ctx.Done():
			return
		case <-time.After(100 * time.Millisecond):
			// Periodic check to allow context cancellation to work
			continue
		default:
			// Set deadline to prevent Accept from blocking indefinitely
			n.listener.SetDeadline(time.Now().Add(500 * time.Millisecond))
			conn, err := n.listener.Accept()
			if err != nil {
				if n.ctx.Err() != nil {
					return
				}
				// Check if it's a timeout - that's expected
				if netErr, ok := err.(net.Error); ok && netErr.Timeout() {
					continue
				}
				// Log only non-temporary errors
				if netErr, ok := err.(net.Error); !ok || !netErr.Temporary() {
					log.Printf("Accept error: %v", err)
				}
				continue
			}

			// Reset deadline for handled connection
			n.listener.SetDeadline(time.Now().Add(1 * time.Second))
			n.handleConnection(conn)
		}
	}
}

func (n *NetworkManager) handleConnection(conn net.Conn) {
	defer conn.Close()

	// Set read deadline to prevent test hanging
	conn.SetReadDeadline(time.Now().Add(5 * time.Second))

	// Read peer handshake - limit scanner buffer to prevent blocking
	scanner := bufio.NewScanner(conn)
	scanner.Buffer(make([]byte, 1024), 1024)
	if !scanner.Scan() {
		return
	}

	handshake := strings.TrimSpace(scanner.Text())
	parts := strings.Split(handshake, ":")
	if len(parts) != 2 || parts[0] != "KNIRV" {
		return
	}

	peerID := parts[1]

	// Send our handshake
	fmt.Fprintf(conn, "KNIRV:%s\n", n.peerID)

	n.mu.Lock()
	n.connections[peerID] = conn
	n.peers[peerID] = &types.PeerInfo{
		PeerID:   peerID,
		Addrs:    []string{conn.RemoteAddr().String()},
		LastSeen: time.Now(),
	}
	n.mu.Unlock()

	// Handle messages from this peer
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}

		var msg types.ProtocolMessage
		if err := json.Unmarshal([]byte(line), &msg); err != nil {
			log.Printf("Failed to decode message: %v", err)
			continue
		}

		n.handleMessage(msg)
	}
}

func (n *NetworkManager) CreateNetwork(cfg types.NetworkConfig) (string, error) {
	if err := n.Initialize(); err != nil {
		return "", err
	}

	n.mu.Lock()
	defer n.mu.Unlock()

	if _, exists := n.networks[cfg.NetworkID]; exists {
		return cfg.NetworkID, nil
	}

	cfg.Collections = make(map[string]bool)
	n.networks[cfg.NetworkID] = &cfg
	n.stats[cfg.NetworkID] = &types.NetworkStats{NetworkID: cfg.NetworkID}

	log.Printf("Created network %s", cfg.NetworkID)
	return cfg.NetworkID, nil
}

func (n *NetworkManager) JoinNetwork(networkID string, bootstrapPeers []string) error {
	if err := n.Initialize(); err != nil {
		return err
	}

	n.mu.Lock()
	if _, exists := n.networks[networkID]; !exists {
		n.networks[networkID] = &types.NetworkConfig{
			NetworkID:   networkID,
			Name:        fmt.Sprintf("Network %s", networkID),
			Collections: make(map[string]bool),
		}
		n.stats[networkID] = &types.NetworkStats{NetworkID: networkID}
	}
	n.mu.Unlock()

	// Connect to bootstrap peers
	for _, addr := range bootstrapPeers {
		go n.connectToPeer(addr)
	}

	return nil
}

func (n *NetworkManager) connectToPeer(address string) {
	conn, err := net.Dial("tcp", address)
	if err != nil {
		log.Printf("Failed to connect to %s: %v", address, err)
		return
	}

	// Send handshake
	fmt.Fprintf(conn, "KNIRV:%s\n", n.peerID)

	// Read response
	scanner := bufio.NewScanner(conn)
	if !scanner.Scan() {
		conn.Close()
		return
	}

	response := strings.TrimSpace(scanner.Text())
	parts := strings.Split(response, ":")
	if len(parts) != 2 || parts[0] != "KNIRV" {
		conn.Close()
		return
	}

	peerID := parts[1]

	n.mu.Lock()
	n.connections[peerID] = conn
	n.peers[peerID] = &types.PeerInfo{
		PeerID:   peerID,
		Addrs:    []string{address},
		LastSeen: time.Now(),
	}
	n.mu.Unlock()

	log.Printf("Connected to peer %s at %s", peerID, address)

	// Handle messages from this peer
	go func() {
		defer conn.Close()
		for scanner.Scan() {
			line := strings.TrimSpace(scanner.Text())
			if line == "" {
				continue
			}

			var msg types.ProtocolMessage
			if err := json.Unmarshal([]byte(line), &msg); err != nil {
				log.Printf("Failed to decode message: %v", err)
				continue
			}

			n.handleMessage(msg)
		}
	}()
}

func (n *NetworkManager) LeaveNetwork(networkID string) error {
	n.mu.Lock()
	defer n.mu.Unlock()

	if _, ok := n.networks[networkID]; !ok {
		return nil
	}

	delete(n.networks, networkID)
	delete(n.stats, networkID)

	log.Printf("Left network %s", networkID)
	return nil
}

func (n *NetworkManager) AddCollectionToNetwork(networkID, collectionName string) error {
	n.mu.Lock()
	netCfg, ok := n.networks[networkID]
	n.mu.Unlock()
	if !ok {
		return errors.New("network not found")
	}

	n.mu.Lock()
	netCfg.Collections[collectionName] = true
	if st, ok := n.stats[networkID]; ok {
		st.CollectionsShared = len(netCfg.Collections)
	}
	n.mu.Unlock()

	// Announce collection to all connected peers
	return n.BroadcastMessage(networkID, types.ProtocolMessage{
		Type:      types.MsgCollectionAnnounce,
		NetworkID: networkID,
		SenderID:  n.GetPeerID(),
		Timestamp: time.Now().UnixMilli(),
		Payload:   map[string]string{"collection": collectionName},
	})
}

func (n *NetworkManager) RemoveCollectionFromNetwork(networkID, collectionName string) error {
	n.mu.Lock()
	defer n.mu.Unlock()
	netCfg, ok := n.networks[networkID]
	if !ok {
		return nil
	}
	delete(netCfg.Collections, collectionName)
	if st, ok := n.stats[networkID]; ok {
		st.CollectionsShared = len(netCfg.Collections)
	}
	return nil
}

func (n *NetworkManager) GetNetworkCollections(networkID string) []string {
	n.mu.RLock()
	defer n.mu.RUnlock()
	netCfg, ok := n.networks[networkID]
	if !ok {
		return nil
	}
	out := make([]string, 0, len(netCfg.Collections))
	for c := range netCfg.Collections {
		out = append(out, c)
	}
	return out
}

func (n *NetworkManager) BroadcastMessage(networkID string, msg types.ProtocolMessage) error {
	if !n.initialized {
		return errors.New("not initialized")
	}

	data, err := json.Marshal(msg)
	if err != nil {
		return err
	}

	n.mu.RLock()
	conns := make([]net.Conn, 0, len(n.connections))
	for _, conn := range n.connections {
		conns = append(conns, conn)
	}
	st := n.stats[networkID]
	n.mu.RUnlock()

	for _, conn := range conns {
		go func(c net.Conn) {
			_, err := fmt.Fprintf(c, "%s\n", data)
			if err != nil {
				log.Printf("Failed to send message: %v", err)
				return
			}

			if st != nil {
				n.mu.Lock()
				st.OperationsSent++
				st.BytesTransferred += int64(len(data))
				n.mu.Unlock()
			}
		}(conn)
	}

	return nil
}

func (n *NetworkManager) SendToPeer(peerID string, networkID string, msg types.ProtocolMessage) error {
	if !n.initialized {
		return errors.New("not initialized")
	}

	data, err := json.Marshal(msg)
	if err != nil {
		return err
	}

	n.mu.RLock()
	conn, ok := n.connections[peerID]
	st := n.stats[networkID]
	n.mu.RUnlock()

	if !ok {
		return errors.New("peer not connected")
	}

	_, err = fmt.Fprintf(conn, "%s\n", data)
	if err != nil {
		return err
	}

	if st != nil {
		n.mu.Lock()
		st.OperationsSent++
		st.BytesTransferred += int64(len(data))
		n.mu.Unlock()
	}

	return nil
}

func (n *NetworkManager) OnMessage(mt types.MessageType, handler MessageHandler) {
	n.mu.Lock()
	defer n.mu.Unlock()
	n.handlers[mt] = append(n.handlers[mt], handler)
}

func (n *NetworkManager) GetNetworkStats(networkID string) *types.NetworkStats {
	n.mu.RLock()
	defer n.mu.RUnlock()
	st := n.stats[networkID]
	if st != nil {
		st.ConnectedPeers = len(n.connections)
	}
	return st
}

func (n *NetworkManager) GetNetworks() []*types.NetworkConfig {
	n.mu.RLock()
	defer n.mu.RUnlock()
	out := make([]*types.NetworkConfig, 0, len(n.networks))
	for _, v := range n.networks {
		out = append(out, v)
	}
	return out
}

func (n *NetworkManager) GetPeerID() string { return n.peerID }

func (n *NetworkManager) Shutdown() error {
	n.cancel()

	n.mu.Lock()
	defer n.mu.Unlock()

	if n.listener != nil {
		n.listener.Close()
	}

	for _, conn := range n.connections {
		conn.Close()
	}

	n.connections = make(map[string]net.Conn)
	n.initialized = false

	return nil
}

func (n *NetworkManager) handleMessage(msg types.ProtocolMessage) {
	n.mu.RLock()
	handlers := n.handlers[msg.Type]
	n.mu.RUnlock()

	for _, h := range handlers {
		go func(fn MessageHandler) {
			defer func() { _ = recover() }()
			fn(msg)
		}(h)
	}
}

package network

import (
	"bytes"
	"context"
	"fmt"
	"io"

	"github.com/apache/arrow/go/v15/arrow"
	"github.com/apache/arrow/go/v15/arrow/array"
	"github.com/apache/arrow/go/v15/arrow/ipc"
	"github.com/apache/arrow/go/v15/arrow/memory"

	stor "github.com/knirvcorp/knirvbase/internal/storage"
	"github.com/knirvcorp/knirvbase/pkg/nrv"
)

type FlightServer struct {
	storage *stor.NRVStorage
	memPool memory.Allocator
	schema  *arrow.Schema
}

func NewFlightServer(storage *stor.NRVStorage) *FlightServer {
	fs := &FlightServer{
		storage: storage,
		memPool: memory.NewGoAllocator(),
	}
	fs.schema = fs.bracketArrowSchema()
	return fs
}

func (s *FlightServer) bracketArrowSchema() *arrow.Schema {
	asicType := &arrow.FixedSizeBinaryType{ByteWidth: nrv.BracketSize}
	return arrow.NewSchema([]arrow.Field{
		{Name: "bracket_id", Type: arrow.BinaryTypes.String},
		{Name: "frame_id", Type: arrow.BinaryTypes.String},
		{Name: "frame_timestamp_unix", Type: arrow.PrimitiveTypes.Int64},
		{Name: "payload_asic", Type: asicType},
		{Name: "drift_score", Type: arrow.PrimitiveTypes.Float64},
		{Name: "bracket_type", Type: arrow.BinaryTypes.String},
	}, nil)
}

func (s *FlightServer) Schema() *arrow.Schema {
	return s.schema
}

func (s *FlightServer) parseTicket(ticket string) (collection string, goldOnly bool, err error) {
	parts := splitTicket(ticket)
	if len(parts) != 2 {
		return "", false, fmt.Errorf("flight: invalid ticket format, expected <stream>.<collection>")
	}
	streamType, collection := parts[0], parts[1]
	goldOnly = streamType == "gold"
	return collection, goldOnly, nil
}

func splitTicket(ticket string) []string {
	var parts []string
	var current []byte
	for i := 0; i < len(ticket); i++ {
		if ticket[i] == '.' {
			parts = append(parts, string(current))
			current = nil
		} else {
			current = append(current, ticket[i])
		}
	}
	if len(current) > 0 {
		parts = append(parts, string(current))
	}
	return parts
}

type BracketStreamServer interface {
	Send(*BracketBatch) error
	Context() context.Context
}

type BracketBatch struct {
	Data []byte
}

func (s *FlightServer) StreamBrackets(ticket string, server BracketStreamServer) error {
	collection, goldOnly, err := s.parseTicket(ticket)
	if err != nil {
		return err
	}

	bracketCh, err := s.storage.StreamBrackets(server.Context(), collection, goldOnly)
	if err != nil {
		return err
	}

	batchSize := 1024
	return s.streamBatches(server, bracketCh, batchSize)
}

func bracketFrameUnix(b *nrv.Bracket) int64 {
	if b == nil {
		return 0
	}
	if b.FrameUnix != 0 {
		return b.FrameUnix
	}
	return int64(b.SubSecondUS)
}

func bracketDriftScore(b *nrv.Bracket) float64 {
	if b == nil || b.Meta == nil {
		return 0
	}
	return b.Meta.DriftScore
}

func bracketTypeStr(b *nrv.Bracket) string {
	if b == nil || b.Meta == nil || b.Meta.Type == "" {
		return string(nrv.DeltaTypeI)
	}
	return string(b.Meta.Type)
}

func appendBracketRecord(recordBuilder *array.RecordBuilder, bracket *nrv.Bracket) {
	wire := nrv.EncodeBracket(bracket)
	recordBuilder.Field(0).(*array.StringBuilder).Append(bracket.ID)
	recordBuilder.Field(1).(*array.StringBuilder).Append(bracket.FrameID)
	recordBuilder.Field(2).(*array.Int64Builder).Append(bracketFrameUnix(bracket))
	recordBuilder.Field(3).(*array.FixedSizeBinaryBuilder).Append(wire[:])
	recordBuilder.Field(4).(*array.Float64Builder).Append(bracketDriftScore(bracket))
	recordBuilder.Field(5).(*array.StringBuilder).Append(bracketTypeStr(bracket))
}

func (s *FlightServer) streamBatches(server BracketStreamServer, bracketCh <-chan *nrv.Bracket, batchSize int) error {
	recordBuilder := array.NewRecordBuilder(s.memPool, s.schema)
	defer func() {
		if recordBuilder != nil {
			recordBuilder.Release()
		}
	}()

	flushBatch := func() error {
		record := recordBuilder.NewRecord()
		if record == nil {
			return nil
		}
		defer record.Release()

		var buf bytes.Buffer
		writer := ipc.NewWriter(&buf, ipc.WithSchema(s.schema))
		if err := writer.Write(record); err != nil {
			writer.Close()
			return err
		}
		writer.Close()

		return server.Send(&BracketBatch{Data: buf.Bytes()})
	}

	var batchCount int

	for {
		select {
		case <-server.Context().Done():
			return server.Context().Err()
		case bracket, ok := <-bracketCh:
			if !ok {
				if batchCount > 0 {
					return flushBatch()
				}
				return nil
			}

			appendBracketRecord(recordBuilder, bracket)
			batchCount++

			if batchCount >= batchSize {
				if err := flushBatch(); err != nil {
					return err
				}
				recordBuilder.Release()
				recordBuilder = array.NewRecordBuilder(s.memPool, s.schema)
				batchCount = 0
			}
		}
	}
}

func BracketsToFlightData(brackets []*nrv.Bracket) ([]byte, error) {
	if len(brackets) == 0 {
		return nil, nil
	}

	memPool := memory.NewGoAllocator()
	server := &FlightServer{memPool: memPool}
	schema := server.bracketArrowSchema()

	recordBuilder := array.NewRecordBuilder(memPool, schema)
	defer recordBuilder.Release()

	for _, b := range brackets {
		appendBracketRecord(recordBuilder, b)
	}

	record := recordBuilder.NewRecord()
	if record == nil {
		return nil, nil
	}
	defer record.Release()

	var buf bytes.Buffer
	writer := ipc.NewWriter(&buf, ipc.WithSchema(schema))
	if err := writer.Write(record); err != nil {
		writer.Close()
		return nil, err
	}
	writer.Close()

	return buf.Bytes(), nil
}

func FlightDataToBrackets(data []byte) ([]*nrv.Bracket, error) {
	if len(data) == 0 {
		return nil, nil
	}

	reader, err := ipc.NewReader(bytes.NewReader(data))
	if err != nil {
		return nil, err
	}

	var brackets []*nrv.Bracket

	for reader.Next() {
		record := reader.Record()
		count := int(record.NumRows())

		idCol := record.Column(0).(*array.String)
		frameIDCol := record.Column(1).(*array.String)
		frameUnixCol := record.Column(2).(*array.Int64)
		asicCol := record.Column(3).(*array.FixedSizeBinary)
		driftCol := record.Column(4).(*array.Float64)
		typeCol := record.Column(5).(*array.String)

		for i := 0; i < count; i++ {
			var raw [nrv.BracketSize]byte
			copy(raw[:], asicCol.Value(i))
			dec := nrv.DecodeBracket(raw)
			bp := new(nrv.Bracket)
			*bp = dec
			bp.ID = idCol.Value(i)
			bp.FrameID = frameIDCol.Value(i)
			bp.FrameUnix = frameUnixCol.Value(i)
			bp.Meta = &nrv.BracketMeta{
				ID:         idCol.Value(i),
				Type:       nrv.DeltaType(typeCol.Value(i)),
				DriftScore: driftCol.Value(i),
			}
			brackets = append(brackets, bp)
		}
		record.Release()
	}

	return brackets, nil
}

// euclideanDistanceFloat32 calculates the squared Euclidean distance between two
// 16-dimensional float32 vectors. Each Bracket's Projections [32]byte field
// encodes a 16-dimensional LSH vector (2 bytes per dimension, uint16 normalized
// to float32). This distance drives the I/P-bracket decision: a new I-bracket
// is emitted whenever the drift score exceeds the configured threshold.
//
// Usage: convert a Bracket's Projections to [16]float32 via projectionsToFloat32,
// then compare current vs. anchor bracket to produce the drift_score stored in
// BracketMeta and the frame's bracket_index entry.
func euclideanDistanceFloat32(a, b [16]float32) float64 {
	var sum float64
	for i := 0; i < 16; i++ {
		diff := float64(a[i] - b[i])
		sum += diff * diff
	}
	return sum
}

// projectionsToFloat32 interprets a Bracket's 32-byte Projections field as a
// 16-dimensional LSH vector. Each pair of bytes encodes one uint16 dimension,
// which is normalized to the float32 range [0.0, 1.0].
func projectionsToFloat32(p [32]byte) [16]float32 {
	var v [16]float32
	for i := 0; i < 16; i++ {
		val := uint16(p[i*2]) | uint16(p[i*2+1])<<8
		v[i] = float32(val) / 65535.0
	}
	return v
}

// CalcBracketDriftScore returns the Euclidean drift between two brackets based
// on their 16-dimensional LSH Projections. The result is stored as DriftScore
// in BracketMeta and used by the FrameTicker to decide when to anchor a new
// I-bracket vs. emitting a P-bracket (delta).
func CalcBracketDriftScore(current, anchor *nrv.Bracket) float64 {
	if current == nil || anchor == nil {
		return 0
	}
	return euclideanDistanceFloat32(
		projectionsToFloat32(current.Projections),
		projectionsToFloat32(anchor.Projections),
	)
}

type FlightClient struct {
	conn    io.Reader
	memPool memory.Allocator
}

func NewFlightClient(conn io.Reader) *FlightClient {
	return &FlightClient{
		conn:    conn,
		memPool: memory.NewGoAllocator(),
	}
}

func (c *FlightClient) StreamBrackets(ctx context.Context, ticket string) ([]*nrv.Bracket, error) {
	_, _ = ctx, ticket
	reader, err := ipc.NewReader(c.conn)
	if err != nil {
		return nil, err
	}

	var brackets []*nrv.Bracket

	for reader.Next() {
		record := reader.Record()
		count := int(record.NumRows())

		idCol := record.Column(0).(*array.String)
		frameIDCol := record.Column(1).(*array.String)
		frameUnixCol := record.Column(2).(*array.Int64)
		asicCol := record.Column(3).(*array.FixedSizeBinary)
		driftCol := record.Column(4).(*array.Float64)
		typeCol := record.Column(5).(*array.String)

		for i := 0; i < count; i++ {
			var raw [nrv.BracketSize]byte
			copy(raw[:], asicCol.Value(i))
			dec := nrv.DecodeBracket(raw)
			bp := new(nrv.Bracket)
			*bp = dec
			bp.ID = idCol.Value(i)
			bp.FrameID = frameIDCol.Value(i)
			bp.FrameUnix = frameUnixCol.Value(i)
			bp.Meta = &nrv.BracketMeta{
				ID:         idCol.Value(i),
				Type:       nrv.DeltaType(typeCol.Value(i)),
				DriftScore: driftCol.Value(i),
			}
			brackets = append(brackets, bp)
		}
		record.Release()
	}

	return brackets, nil
}

