	gatewayURL   string
	networkID    string
	callbackPath string
	client       *http.Client
	mu           sync.RWMutex
	stopChan     chan struct{}
}

// NewGatewayProxy creates a new gateway proxy client.
func NewGatewayProxy(gatewayURL, networkID, callbackPath string) *GatewayProxy {
	return &GatewayProxy{
		gatewayURL:   gatewayURL,
		networkID:    networkID,
		callbackPath: callbackPath,
		client: &http.Client{
			Timeout: 10 * time.Second,
		},
		stopChan: make(chan struct{}),
	}
}

// Register tells KNIRVGATEWAY where to send CRDT operations.
func (g *GatewayProxy) Register() error {
	payload := map[string]string{
		"socket_path": g.callbackPath,
		"network_id":  g.networkID,
	}
	data, _ := json.Marshal(payload)
	resp, err := g.client.Post(
		g.gatewayURL+"/knirvbase/register-callback",
		"application/json",
		bytes.NewReader(data),
	)
	if err != nil {
		return fmt.Errorf("register callback: %w", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return fmt.Errorf("register-callback returned %d", resp.StatusCode)
	}
	return nil
}

