package network

import "log"

// startTransport is a no-op in the default build. The legacy custom TCP P2P
// transport is disabled unless the binary is built with the `legacy_tcp` tag.
// New deployments should route consensus through the p2pconsensus package.
func (n *NetworkManager) startTransport() {
	log.Printf("legacy P2P TCP transport disabled (build without -tags legacy_tcp)")
}

// connectToPeer is a no-op in the default build (see startTransport).
func (n *NetworkManager) connectToPeer(address string) {}

package p2pconsensus

import (
	"bytes"
	"testing"
)

func TestServiceIDAndTopicBindToSecret(t *testing.T) {
	open1 := ServiceID("net", "")
	open2 := ServiceID("net", "")
	if open1 != open2 {
		t.Fatal("open network IDs should be deterministic")
	}

	s1 := ServiceID("net", "secretA")
	s2 := ServiceID("net", "secretB")
	if s1 == s2 {
		t.Fatal("different secrets must produce different service IDs")
	}
	if s1 == open1 {
		t.Fatal("secret-bound ID must differ from open ID")
	}

	// Topic must also be secret-bound.
	if Topic("net", "secretA") == Topic("net", "secretB") {
		t.Fatal("different secrets must produce different topics")
	}
	if Topic("net", "") == Topic("net", "secretA") {
		t.Fatal("open topic must differ from secret-bound topic")
	}
}

func TestSignAndVerifyMessage(t *testing.T) {
	payload := []byte(`{"collection":"c","document_id":"d"}`)

	// With a secret, signing is deterministic and verifiable.
	sig := SignMessage("net", "topsecret", payload)
	if sig == "" {
		t.Fatal("expected non-empty signature with secret")
	}
	if !VerifyMessage("net", "topsecret", sig, payload) {
		t.Fatal("valid signature should verify")
	}
	// Tampered payload must fail.
	if VerifyMessage("net", "topsecret", sig, []byte("tampered")) {
		t.Fatal("tampered payload must not verify")
	}
	// Wrong secret must fail.
	if VerifyMessage("net", "wrong", sig, payload) {
		t.Fatal("wrong secret must not verify")
	}
}

func TestVerifyMessageOpenNetwork(t *testing.T) {
	payload := []byte("hello")
	// No secret configured: any/empty signature is accepted.
	if !VerifyMessage("net", "", "", payload) {
		t.Fatal("open network should accept unsigned payloads")
	}
	if !VerifyMessage("net", "", "anything", payload) {
		t.Fatal("open network should accept arbitrary signature")
	}
	// Once a secret is set, an empty signature must be rejected.
	if VerifyMessage("net", "secret", "", payload) {
		t.Fatal("secret-bound network must reject empty signature")
	}
}

func TestSignMessageEmptySecret(t *testing.T) {
	if sig := SignMessage("net", "", []byte("x")); sig != "" {
		t.Fatalf("open network should produce no signature, got %q", sig)
	}
}

func TestHMACCommutativity(t *testing.T) {
	payload := []byte("consistent")
	a := SignMessage("n", "s", payload)
	b := SignMessage("n", "s", payload)
	if !bytes.Equal([]byte(a), []byte(b)) {
		t.Fatal("signatures must be deterministic for identical inputs")
	}
}

package p2pconsensus

import (
	"context"
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestGatewayProxySignsPublishWithSecret(t *testing.T) {
	var gotSig string
	var gotTopic string
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		gotSig = r.Header.Get("X-KNIRV-Signature")
		switch r.URL.Path {
		case "/knirvbase/register-callback":
			_ = r.ParseForm()
		case "/knirvbase/publish-op":
			body := make([]byte, r.ContentLength)
			_, _ = r.Body.Read(body)
			// Re-verify using the shared secret via the exported helper.
			if !VerifyMessage("net", "hush", body) {
				t.Errorf("server-side recomputed signature mismatch")
			}
		}
		w.WriteHeader(http.StatusOK)
	}))
	defer srv.Close()

	// The register payload carries the secret-bound topic.
	regSrv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		_ = r.ParseForm()
		gotTopic = r.FormValue("topic")
		w.WriteHeader(http.StatusOK)
	}))
	defer regSrv.Close()

	// Use the register server for Register, publish server for Publish.
	g := NewGatewayProxy(srv.URL, "net", "/tmp/knirv.sock", "hush")
	if err := g.Register(); err != nil {
		t.Fatalf("register: %v", err)
	}
	if gotTopic == "" {
		t.Fatal("expected topic in register payload")
	}

	pub := NewGatewayProxy(srv.URL, "net", "/tmp/knirv.sock", "hush")
	op := OperationEnvelope{Collection: "c", DocumentID: "d", Data: []byte(`{"x":1}`)}
	if err := pub.PublishOperation(context.Background(), op); err != nil {
		t.Fatalf("publish: %v", err)
	}
	if gotSig == "" {
		t.Fatal("expected X-KNIRV-Signature header on publish")
	}
}

func TestGatewayProxyPublishOpenNetworkNoSignature(t *testing.T) {
	var gotSig string
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		gotSig = r.Header.Get("X-KNIRV-Signature")
		w.WriteHeader(http.StatusOK)
	}))
	defer srv.Close()

	g := NewGatewayProxy(srv.URL, "net", "/tmp/knirv.sock")
	op := OperationEnvelope{Collection: "c", DocumentID: "d"}
	if err := g.PublishOperation(context.Background(), op); err != nil {
		t.Fatalf("publish: %v", err)
	}
	if gotSig != "" {
		t.Fatalf("open network should not sign, got %q", gotSig)
	}
}

